const (
	EntityTypeNameOrganization EntityTypeName = "Organization"
	EntityTypeNamePaypoint     EntityTypeName = "Paypoint"
	EntityTypeNameCustomer     EntityTypeName = "Customer"
	EntityTypeNameTemplate     EntityTypeName = "Template"
	EntityTypeNameApplication  EntityTypeName = "Application"
	EntityTypeNameBankAccount  EntityTypeName = "BankAccount"
	EntityTypeNameAddress      EntityTypeName = "Address"
)

func NewEntityTypeNameFromString(s string) (EntityTypeName, error) {
	switch s {
	case "Organization":
		return EntityTypeNameOrganization, nil
	case "Paypoint":
		return EntityTypeNamePaypoint, nil
	case "Customer":
		return EntityTypeNameCustomer, nil
	case "Template":
		return EntityTypeNameTemplate, nil
	case "Application":
		return EntityTypeNameApplication, nil
	case "BankAccount":
		return EntityTypeNameBankAccount, nil
	case "Address":
		return EntityTypeNameAddress, nil
	}
	var t EntityTypeName
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

